1: //! 模型端点错误的统一分类与人话映射（审计 A0：错误在 UI/日志/导出三处都查不到）。
2: //!
3: //! 设计原则：
4: //! 1. **分类与文案只在一处**：HTTP 状态与错误体 → [`ModelError`]；界面只读 `human`，
5: //!    不再各自拼“回合以 failed 结束”。
6: //! 2. **原始信息必须留得住**：`provider_code` / `provider_message` / `http_status`
7: //!    原样带出（脱敏后），供界面展开与导出对账。
8: //! 3. **脱敏先于截断**：与 `error_snippet` 同一条纪律，先整串替换凭据再截断。
9: 
10: use std::fmt;
11: 
12: /// 错误大类。前端只认 `code()` 的稳定字符串，不依赖具体 HTTP 码。
13: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
14: pub enum ModelErrorKind {
15:     /// 401/403：密钥无效或无权限。
16:     Auth,
17:     /// 402，或错误体点名余额/额度不足。
18:     Quota,
19:     /// 429：触发限流。
20:     RateLimited,
21:     /// 建连/首包/流空闲超时。
22:     Timeout,
23:     /// 连接失败、SSE 断流等网络问题。
24:     Network,
25:     /// 5xx：服务端错误。
26:     Server,
27:     /// 404/405：该地址没有这个接口（常见于把 base_url 指到只支持 chat 的端点）。
28:     EndpointUnsupported,
29:     /// 400/422：请求本身被拒。
30:     BadRequest,
31:     /// 流正常结束，但没有任何增量、没有工具调用、也没有 usage。
32:     EmptyResponse,
33:     /// 其它。
34:     Unknown,
35: }
36: 
37: /// 一次模型端点失败的完整描述。
38: #[derive(Debug, Clone, PartialEq, Eq)]
39: pub struct ModelError {
40:     pub kind: ModelErrorKind,
41:     pub http_status: Option<u16>,
42:     /// 端点错误体里的 `error.code` / `error.type`（脱敏后）。
43:     pub provider_code: Option<String>,
44:     /// 端点错误体里的 `error.message`（脱敏后，已截断）。
45:     pub provider_message: Option<String>,
46:     /// 给用户看的一句话。
47:     pub human: String,
48:     /// 端点 `Retry-After` 响应头（毫秒）。只有非 2xx 响应才可能有；解析不出即 `None`。
49:     /// 重试策略据此优先于指数退避（`model_client/retry.rs`）。
50:     pub retry_after_ms: Option<u64>,
51: }
52: 
53: impl ModelError {
54:     /// 组合一个错误；`provider_code` / `provider_message` 已经过脱敏。
55:     pub fn new(
56:         kind: ModelErrorKind,
57:         http_status: Option<u16>,
58:         provider_code: Option<String>,
59:         provider_message: Option<String>,
60:         human: String,
61:     ) -> Self {
62:         Self { kind, http_status, provider_code, provider_message, human, retry_after_ms: None }
63:     }
64: 
65:     /// 带上端点的 `Retry-After`（毫秒）。重试策略据此优先于指数退避。
66:     pub fn with_retry_after(mut self, retry_after_ms: Option<u64>) -> Self {
67:         self.retry_after_ms = retry_after_ms;
68:         self
69:     }
70: 
71:     /// 稳定错误码（前端按它做本地化与统计，不要依赖 HTTP 码）。
72:     pub fn code(&self) -> &'static str {
73:         match self.kind {
74:             ModelErrorKind::Auth => "AUTH",
75:             ModelErrorKind::Quota => "QUOTA",
76:             ModelErrorKind::RateLimited => "RATE_LIMIT",
77:             ModelErrorKind::Timeout => "TIMEOUT",
78:             ModelErrorKind::Network => "NETWORK",
79:             ModelErrorKind::Server => "SERVER",
80:             ModelErrorKind::EndpointUnsupported => "ENDPOINT_UNSUPPORTED",
81:             ModelErrorKind::BadRequest => "BAD_REQUEST",
82:             ModelErrorKind::EmptyResponse => "EMPTY_RESPONSE",
83:             ModelErrorKind::Unknown => "UNKNOWN",
84:         }
85:     }
86: 
87:     /// HTTP 状态 + 错误体 → 结构化错误。
88:     ///
89:     /// 分类顺序：先看错误体里的额度关键词（有些端点用 400/403 报余额不足），
90:     /// 再看状态码。这样“余额不足”不会被误报成“密钥无效”。
91:     pub fn from_status(status: u16, body: &str) -> Self {
92:         let (provider_code, provider_message) = provider_fields(body);
93:         let kind = if quota_hit(provider_code.as_deref(), provider_message.as_deref()) {
94:             ModelErrorKind::Quota
95:         } else {
96:             match status {
97:                 401 | 403 => ModelErrorKind::Auth,
98:                 402 => ModelErrorKind::Quota,
99:                 404 | 405 => ModelErrorKind::EndpointUnsupported,
100:                 429 => ModelErrorKind::RateLimited,
101:                 500..=599 => ModelErrorKind::Server,
102:                 400 | 422 => ModelErrorKind::BadRequest,
103:                 _ => ModelErrorKind::Unknown,
104:             }
105:         };
106:         let human = match kind {
107:             ModelErrorKind::Auth => "密钥无效".to_string(),
108:             ModelErrorKind::Quota => "余额不足".to_string(),
109:             ModelErrorKind::RateLimited => "请求过于频繁，已被限流".to_string(),
110:             ModelErrorKind::Timeout => "网络超时".to_string(),
111:             ModelErrorKind::Network => "无法连接到模型服务".to_string(),
112:             ModelErrorKind::Server => format!("模型服务端错误（HTTP {status}）"),
113:             ModelErrorKind::EndpointUnsupported => format!("该地址不支持此接口（HTTP {status}）"),
114:             ModelErrorKind::BadRequest => format!("请求被拒绝（HTTP {status}）"),
115:             ModelErrorKind::EmptyResponse => "模型返回了空响应".to_string(),
116:             ModelErrorKind::Unknown => format!("未知错误（HTTP {status}）"),
117:         };
118:         Self::new(kind, Some(status), provider_code, provider_message, human)
119:     }
120: 
121:     /// 流内错误体（SSE 的 `error` / `response.failed` 事件）→ 结构化错误。
122:     ///
123:     /// 这类事件没有 HTTP 状态码，只能按错误体里的关键词分类；取不到就不猜。
124:     /// 用户可见的一句话优先用端点原文（已脱敏），它比"未知错误"更有信息量。
125:     pub fn from_body(value: Option<&serde_json::Value>) -> Self {
126:         let (provider_code, provider_message) = value.map(provider_fields_value).unwrap_or((None, None));
127:         let kind = if quota_hit(provider_code.as_deref(), provider_message.as_deref()) {
128:             ModelErrorKind::Quota
129:         } else {
130:             ModelErrorKind::Unknown
131:         };
132:         let human = match kind {
133:             ModelErrorKind::Quota => "余额不足".to_string(),
134:             _ => provider_message.clone().unwrap_or_else(|| "模型服务返回错误".to_string()),
135:         };
136:         Self::new(kind, None, provider_code, provider_message, human)
137:     }
138: 
139:     /// reqwest 传输错误 → 分类（超时 / 连接失败 / 其它网络问题）。
140:     pub fn from_reqwest(error: &reqwest::Error) -> Self {
141:         let (kind, human) = if error.is_timeout() {
142:             (ModelErrorKind::Timeout, "网络超时".to_string())
143:         } else if error.is_connect() {
144:             (ModelErrorKind::Network, "无法连接到模型服务".to_string())
145:         } else {
146:             (ModelErrorKind::Network, "模型请求失败".to_string())
147:         };
148:         Self::new(kind, None, None, Some(sanitize(&error.to_string())), human)
149:     }
150: 
151:     /// 本地限时（首包/流空闲）→ 超时。
152:     pub fn timeout(message: impl Into<String>) -> Self {
153:         Self::new(ModelErrorKind::Timeout, None, None, Some(sanitize(&message.into())), "网络超时".to_string())
154:     }
155: 
156:     /// 流正常结束却什么都没产出 → 空响应（可重试；判定见 `agent_loop`）。
157:     pub fn empty_response() -> Self {
158:         Self::new(
159:             ModelErrorKind::EmptyResponse,
160:             None,
161:             None,
162:             None,
163:             "模型返回了空响应".to_string(),
164:         )
165:     }
166: 
167:     /// SSE 断流等流内错误 → 网络问题。
168:     pub fn stream_broken(message: impl Into<String>) -> Self {
169:         Self::new(
170:             ModelErrorKind::Network,
171:             None,
172:             None,
173:             Some(sanitize(&message.into())),
174:             "模型连接中断".to_string(),
175:         )
176:     }
177: 
178:     /// 构造 HTTP 客户端失败（配置问题，不是网络问题）。
179:     pub fn client_build(message: impl Into<String>) -> Self {
180:         Self::new(
181:             ModelErrorKind::Unknown,
182:             None,
183:             None,
184:             Some(sanitize(&message.into())),
185:             "无法初始化模型请求".to_string(),
186:         )
187:     }
188: }
189: 
190: impl fmt::Display for ModelError {
191:     fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
192:         formatter.write_str(&self.human)
193:     }
194: }
195: 
196: impl std::error::Error for ModelError {}
197: 
198: /// 允许测试桩与旧的字符串错误无缝接入（生产路径一律显式构造分类）。
199: impl From<String> for ModelError {
200:     fn from(message: String) -> Self {
201:         Self::new(
202:             ModelErrorKind::Unknown,
203:             None,
204:             None,
205:             Some(sanitize(&message)),
206:             message,
207:         )
208:     }
209: }
210: 
211: impl From<&str> for ModelError {
212:     fn from(message: &str) -> Self {
213:         Self::from(message.to_string())
214:     }
215: }
216: 
217: /// 错误体里的额度/余额关键词（部分端点用 400/403 报余额不足）。
218: fn quota_hit(code: Option<&str>, message: Option<&str>) -> bool {
219:     let haystack = format!("{} {}", code.unwrap_or_default(), message.unwrap_or_default()).to_ascii_lowercase();
220:     [
221:         "insufficient_quota",
222:         "insufficient_balance",
223:         "insufficient balance",
224:         "quota_exceeded",
225:         "quota exceeded",
226:         "billing_hard_limit_reached",
227:         "余额不足",
228:         "额度不足",
229:     ]
230:     .iter()
231:     .any(|needle| haystack.contains(needle))
232: }
233: 
234: impl From<&ModelError> for crate::events::TurnErrorInfo {
235:     fn from(error: &ModelError) -> Self {
236:         Self {
237:             code: error.code().to_string(),
238:             message: error.human.clone(),
239:             http_status: error.http_status,
240:             provider_code: error.provider_code.clone(),
241:             provider_message: error.provider_message.clone(),
242:             // 次数由采样循环填（它才知道本轮试了几次）；这里只搬运端点原值。
243:             attempts: None,
244:             // 仅在因 `Retry-After` 超过上限而放弃时有值；原样给秒，不四舍五入。
245:             retry_after_secs: error.retry_after_ms.map(|ms| ms / 1000),
246:         }
247:     }
248: }
249: 
250: /// 错误体里提取 `code` / `message`。
251: ///
252: /// 兼容三种常见形态：`{"error":{"code","message"}}`、`{"error":{"type","message"}}`、
253: /// 顶层 `{"code","message"}`（部分自建网关）。取不到就返回 `None`，不猜。
254: fn provider_fields(body: &str) -> (Option<String>, Option<String>) {
255:     let Ok(value) = serde_json::from_str::<serde_json::Value>(body) else {
256:         return (None, None);
257:     };
258:     provider_fields_value(&value)
259: }
260: 
261: /// 同 [`provider_fields`]，输入已是解析后的 JSON（流内事件用）。
262: fn provider_fields_value(value: &serde_json::Value) -> (Option<String>, Option<String>) {
263:     let error = value.get("error").unwrap_or(value);
264:     let code = error
265:         .get("code")
266:         .or_else(|| error.get("type"))
267:         .and_then(json_scalar);
268:     let message = error.get("message").and_then(json_scalar);
269:     (code.map(|text| sanitize(&text)), message.map(|text| sanitize(&text)))
270: }
271: 
272: /// JSON 标量转字符串（数字型 code 也保留）。
273: fn json_scalar(value: &serde_json::Value) -> Option<String> {
274:     match value {
275:         serde_json::Value::String(text) => Some(text.clone()),
276:         serde_json::Value::Number(number) => Some(number.to_string()),
277:         _ => None,
278:     }
279: }
280: 
281: /// 脱敏 → 截断到 300 字符（顺序不可交换，理由同 `error_snippet`）。
282: fn sanitize(text: &str) -> String {
283:     crate::config::redact(text).chars().take(300).collect()
284: }
