10: /// 模型端点错误（`ModelError::code`，见 `model_client/error.rs`）。
11: pub mod model {
12:     pub const AUTH: &str = "AUTH";
13:     pub const QUOTA: &str = "QUOTA";
14:     pub const RATE_LIMIT: &str = "RATE_LIMIT";
15:     pub const TIMEOUT: &str = "TIMEOUT";
16:     pub const NETWORK: &str = "NETWORK";
17:     pub const SERVER: &str = "SERVER";
18:     pub const ENDPOINT_UNSUPPORTED: &str = "ENDPOINT_UNSUPPORTED";
19:     pub const BAD_REQUEST: &str = "BAD_REQUEST";
20:     pub const EMPTY_RESPONSE: &str = "EMPTY_RESPONSE";
21:     pub const UNKNOWN: &str = "UNKNOWN";
22: }
23: 
24: /// 工作区文件读取失败（`workspace_files.rs`）。
25: pub mod workspace_file {
26:     pub const TOO_LARGE: &str = "workspace-file/too-large";
27:     pub const NOT_REGULAR_FILE: &str = "workspace-file/not-regular-file";
28:     pub const NOT_DIRECTORY: &str = "workspace-file/not-directory";
29: }
