77:     /// 第二种 emit 形态：`ModelError::code()` 的 `=> "AUTH"` 分支。
78:     /// 只扫该函数体，避免把同文件里别的字符串误当错误码。
79:     fn code_fn_literals() -> Vec<(PathBuf, usize, String)> {
80:         let file = Path::new(env!("CARGO_MANIFEST_DIR"))
81:             .join("src")
82:             .join("model_client")
83:             .join("error.rs");
84:         let Ok(text) = std::fs::read_to_string(&file) else { return Vec::new() };
85:         let mut found = Vec::new();
86:         let mut inside = false;
87:         for (index, line) in text.lines().enumerate() {
88:             if line.contains("pub fn code(&self)") {
89:                 inside = true;
90:                 continue;
91:             }
92:             if !inside {
93:                 continue;
94:             }
95:             if line.trim() == "}" {
96:                 break;
97:             }
98:             let Some(pos) = line.find("=> \"") else { continue };
99:             let after = &line[pos + "=> \"".len()..];
100:             if let Some(end) = after.find('"') {
101:                 found.push((file.clone(), index + 1, after[..end].to_string()));
102:             }
103:         }
104:         found
105:     }
