107:     /// 扫描生产源码里的 `code: "..."` 字面量（排除 `provider_code` 一类别名），
108:     /// 加上 `ModelError::code()` 的 match 分支。
109:     fn emitted_codes() -> Vec<(PathBuf, usize, String)> {
110:         let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
111:         let mut files = Vec::new();
112:         collect_rs(&root, &mut files);
113:         let mut found = Vec::new();
114:         for file in files {
115:             // 词表自身只有常量与文档注释，不是 emit 点。
116:             if file.file_name().is_some_and(|name| name == "error_codes.rs") {
117:                 continue;
118:             }
119:             let Ok(text) = std::fs::read_to_string(&file) else { continue };
120:             for (index, line) in text.lines().enumerate() {
121:                 // 注释里的 `code: "..."` 是说明文字，不是 emit。
122:                 let trimmed = line.trim_start();
123:                 if trimmed.starts_with("//") || trimmed.starts_with('*') {
124:                     continue;
125:                 }
126:                 let mut rest = line;
127:                 while let Some(pos) = rest.find("code: \"") {
128:                     let boundary_ok = rest[..pos]
129:                         .chars()
130:                         .last()
131:                         .is_none_or(|c| !(c.is_alphanumeric() || c == '_'));
132:                     let after = &rest[pos + "code: \"".len()..];
133:                     if let Some(end) = after.find('"') {
134:                         let code = &after[..end];
135:                         // `format!` 之类的动态拼接交给词表外的构造点自证，不在本扫描范围。
136:                         if boundary_ok && !code.is_empty() && !code.contains('{') {
137:                             found.push((file.clone(), index + 1, code.to_string()));
138:                         }
139:                     }
140:                     rest = after;
141:                 }
142:             }
143:         }
144:         found.extend(code_fn_literals());
145:         found
146:     }
