1: //! 模型请求重试的**纯逻辑**：能不能重试、要等多久。
2: //!
3: //! 刻意不碰 sink、不碰取消令牌、不睡眠——那三样留在 `agent_loop`（它才知道回合、
4: //! 事件与取消语义）。因此本文件不依赖 tokio，单测是确定性的。
5: //!
6: //! 参数与公式照搬 dsh（`llm/llm/src/retry-policy.ts`、`llm/llm-retry/src/index.ts`）：
7: //! 指数退避 + 对称抖动 + 封顶，`Retry-After` 优先。
8: 
9: use std::time::{Duration, SystemTime, UNIX_EPOCH};
10: 
11: use super::ModelErrorKind;
12: 
13: /// 重试策略。字段公开：配置装配与测试都直接按值构造。
14: #[derive(Debug, Clone, PartialEq)]
15: pub struct RetryPolicy {
16:     /// 单个采样步最多重试几次（不含首次请求）。
17:     pub max_retries: u32,
18:     /// 第一次重试的基准等待。
19:     pub initial_delay: Duration,
20:     /// 单次等待的硬上限，也是 `Retry-After` 的可接受上限。
21:     pub max_delay: Duration,
22:     /// 对称抖动比例：`1 ± jitter_ratio`。
23:     pub jitter_ratio: f64,
24: }
25: 
26: impl Default for RetryPolicy {
27:     fn default() -> Self {
28:         // 数值逐项对齐 dsh retry-policy.ts:14-17。
29:         Self {
30:             max_retries: 5,
31:             initial_delay: Duration::from_millis(500),
32:             max_delay: Duration::from_secs(10),
33:             jitter_ratio: 0.1,
34:         }
35:     }
36: }
37: 
38: impl RetryPolicy {
39:     /// 只改次数，其余沿用默认值（`from_config` 的唯一入口）。
40:     pub fn new(max_retries: u32) -> Self {
41:         Self { max_retries, ..Self::default() }
42:     }
43: 
44:     /// 测试与回放用：0 次重试，不产生任何 `model_retry` 事件。
45:     pub fn disabled() -> Self {
46:         Self::new(0)
47:     }
48: 
49:     /// 白名单判定。白名单之外一次失败即终局——不猜、不重试。
50:     pub fn is_retryable(kind: ModelErrorKind) -> bool {
51:         matches!(
52:             kind,
53:             ModelErrorKind::RateLimited
54:                 | ModelErrorKind::Timeout
55:                 | ModelErrorKind::Network
56:                 | ModelErrorKind::Server
57:                 | ModelErrorKind::EmptyResponse
58:         )
59:     }
60: 
61:     /// 第 `retry` 次重试（从 1 起）该等多久；`None` = 放弃重试。
62:     ///
63:     /// - 端点给了 `Retry-After` 就优先采用；超过 `max_delay` 直接放弃，不自行缩短；
64:     /// - 否则指数退避 `initial * 2^(retry-1)`，封顶 `max_delay`，再乘对称抖动并二次封顶。
65:     ///
66:     /// `random01` 由调用方注入（`[0, 1]`），生产用 [`random01`]，测试用固定值。
67:     pub fn delay(&self, retry: u32, provider_retry_after_ms: Option<u64>, random01: f64) -> Option<Duration> {
68:         if retry == 0 || retry > self.max_retries {
69:             return None;
70:         }
71:         if let Some(required) = provider_retry_after_ms {
72:             let required = Duration::from_millis(required);
73:             return (required <= self.max_delay).then_some(required);
74:         }
75:         // `2^(retry-1)` 用移位算，先夹住指数防止手写超大次数时溢出。
76:         let exponent = retry.saturating_sub(1).min(20);
77:         let exponential = self.initial_delay.saturating_mul(1u32 << exponent).min(self.max_delay);
78:         let jitter = 1.0 - self.jitter_ratio + 2.0 * self.jitter_ratio * random01.clamp(0.0, 1.0);
79:         Some(exponential.mul_f64(jitter).min(self.max_delay))
80:     }
81: }
82: 
83: /// 生产用随机源：`[0, 1)`。系统熵源不可用时退回时钟低位，不 panic——
84: /// 抖动只影响等待的分布，不影响正确性。
85: pub fn random01() -> f64 {
86:     let mut bytes = [0u8; 8];
87:     if getrandom::fill(&mut bytes).is_ok() {
88:         // 取高 53 位映射到 [0, 1)，与 f64 尾数精度一致。
89:         return (u64::from_le_bytes(bytes) >> 11) as f64 / (1u64 << 53) as f64;
90:     }
91:     let nanos = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.subsec_nanos()).unwrap_or(0);
92:     f64::from(nanos) / 1e9
93: }
