1: //! 审计 A0-2：端点错误必须映射成一句人话，且原始 code/message 在整个传递链上
2: //! 保持可对账（脱敏后）。
3: //!
4: //! 这里用真实 HTTP 往返测 `stream_body`，而不是只测 `from_status`：401 的映射
5: //! 失败过一次（UI/日志/导出三处都没有 401），只测纯函数会漏掉"非 2xx 分支
6: //! 根本没构造结构化错误"这类断链。
7: 
8: use std::io::{Read as _, Write as _};
9: use std::sync::atomic::{AtomicBool, Ordering};
10: use std::sync::Arc;
11: 
12: use shaniu_lib::model_client::{stream_body, ModelErrorKind, ProviderConfig};
13: 
14: const SECRET: &str = "[REDACTED]";
15: 
16: /// 一次性本地端点：读完请求头后回一段固定响应。
17: struct LocalServer {
18:     port: u16,
19:     stop: Arc<AtomicBool>,
20: }
21: 
22: impl LocalServer {
23:     fn start(status_line: &'static str, body: &'static str) -> Self {
24:         let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
25:         let port = listener.local_addr().unwrap().port();
26:         listener.set_nonblocking(true).unwrap();
27:         let stop = Arc::new(AtomicBool::new(false));
28:         let thread_stop = stop.clone();
29:         std::thread::spawn(move || {
30:             while !thread_stop.load(Ordering::Relaxed) {
31:                 match listener.accept() {
32:                     Ok((mut stream, _)) => {
33:                         // Windows 上 accept 出的 socket 会继承非阻塞标志，必须切回阻塞。
34:                         stream.set_nonblocking(false).unwrap();
35:                         let mut buf = [0u8; 4096];
36:                         let _ = stream.read(&mut buf);
37:                         let response = format!(
38:                             "HTTP/1.1 {status_line}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
39:                             body.len()
40:                         );
41:                         let _ = stream.write_all(response.as_bytes());
42:                         let _ = stream.flush();
43:                     }
44:                     Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => {
45:                         std::thread::sleep(std::time::Duration::from_millis(5));
46:                     }
47:                     Err(_) => break,
48:                 }
49:             }
50:         });
51:         Self { port, stop }
52:     }
53: 
54:     fn provider(&self) -> ProviderConfig {
55:         ProviderConfig {
56:             provider: "openai-chat".into(),
57:             base_url: format!("http://127.0.0.1:{}", self.port),
58:             model: "test-model".into(),
59:             reasoning_effort: None,
60:             headers: Default::default(),
61:         }
62:     }
63: }
64: 
65: impl Drop for LocalServer {
66:     fn drop(&mut self) {
67:         self.stop.store(true, Ordering::Relaxed);
68:     }
69: }
